<script>
  import { onMount } from 'svelte';
  import katexify from '../katexify';

  let dataset = [];
  let trainSet = [];
  let testSet = [];
  let weight = 0;
  let bias = 0;
  let lossHistory = [];
  let weightHistory = [];
  let biasHistory = [];
  let isTraining = false;
  let learningRate = 0.01;
  let epochs = 100;
  let currentEpoch = 0;
  let currentLoss = 0;
  let currentDw = 0;
  let currentDb = 0;
  let currentWeightUpdate = 0;
  let trainSize = 80;
  let featureName = 'Study Hours';
  let targetName = 'Score';
  let predictionInput = '';
  let predictedValue = 0;
  let showPrediction = false;

  let step = 1; // 1: Build Dataset, 2: Split, 3: Init Weights, 4: Train, 5: Predict
  let customWeight = 0;
  let customBias = 0;
  let useCustomWeights = false;
  let visualizationSpeed = 100; // ms between steps
  let gdPath = []; // Gradient descent path points
  let gdCurrentPoint = { x: 0, y: 0 };

  function addDataPoint() {
    const x = parseFloat(document.getElementById('pointX').value);
    const y = parseFloat(document.getElementById('pointY').value);
    
    if (isNaN(x) || isNaN(y)) {
      alert('Please enter valid numbers');
      return;
    }
    
    dataset.push({ x, y });
    document.getElementById('pointX').value = '';
    document.getElementById('pointY').value = '';
  }

  function removePoint(index) {
    dataset.splice(index, 1);
  }

  function loadPreset(type) {
    if (type === 'simple') {
      dataset = [
        { x: 1, y: 2 }, { x: 2, y: 4 }, { x: 3, y: 5 }, { x: 4, y: 4 },
        { x: 5, y: 5 }, { x: 6, y: 7 }, { x: 7, y: 8 }, { x: 8, y: 9 }
      ];
    } else if (type === 'large') {
      dataset = [];
      for (let i = 1; i <= 50; i++) {
        const x = i;
        const y = 2 * x + 1 + (Math.random() - 0.5) * 4;
        dataset.push({ x, y });
      }
    }
  }

  function clearDataset() {
    dataset = [];
  }

  function splitData() {
    const trainCount = Math.floor(dataset.length * (trainSize / 100));
    const shuffled = [...dataset].sort(() => Math.random() - 0.5);
    trainSet = shuffled.slice(0, trainCount);
    testSet = shuffled.slice(trainCount);
  }



  function gradientDescentStep() {
    let dw = 0;
    let db = 0;
    const n = trainSet.length;
    
    trainSet.forEach(point => {
      const prediction = weight * point.x + bias;
      const error = prediction - point.y;
      dw += (2 / n) * error * point.x;
      db += (2 / n) * error;
    });
    
    const weightUpdate = learningRate * dw;
    const biasUpdate = learningRate * db;
    
    currentDw = dw;
    currentDb = db;
    currentWeightUpdate = weightUpdate;
    
    weight = weight - weightUpdate;
    bias = bias - biasUpdate;
  }

  function calculateLoss() {
    let totalLoss = 0;
    const n = trainSet.length;
    trainSet.forEach(point => {
      const prediction = weight * point.x + bias;
      const error = prediction - point.y;
      totalLoss += error * error;
    });
    return totalLoss / n;
  }

  function startTraining() {
    if (isTraining) return;
    
    isTraining = true;
    lossHistory = [];
    weightHistory = [];
    biasHistory = [];
    gdPath = [];
    currentEpoch = 0;
    
    const interval = setInterval(() => {
      if (currentEpoch >= epochs) {
        clearInterval(interval);
        isTraining = false;
        return;
      }
      
      gradientDescentStep();
      const loss = calculateLoss();
      lossHistory.push(loss);
      weightHistory.push(weight);
      biasHistory.push(bias);
      currentLoss = loss;
      
      // Map weight to x coordinate (range -10 to 10) and loss to y coordinate
      const clampedWeight = Math.max(-10, Math.min(10, weight));
      const gdX = ((clampedWeight + 10) / 20) * 360 + 20;
      const maxLoss = Math.max(...lossHistory, 1);
      const gdY = 160 - (loss / maxLoss) * 120;
      gdPath.push({ x: gdX, y: gdY });
      
      currentEpoch++;
      
      if (currentEpoch === epochs) {
        isTraining = false;
      }
    }, visualizationSpeed);
  }

  function makePrediction() {
    const input = parseFloat(predictionInput);
    if (isNaN(input)) {
      alert('Please enter a valid number');
      return;
    }
    const rawPrediction = weight * input + bias;
    
    // Handle very large numbers with scientific notation
    if (Math.abs(rawPrediction) > 1000000) {
      predictedValue = rawPrediction.toExponential(3);
    } else {
      predictedValue = rawPrediction;
    }
    
    showPrediction = true;
  }

  function goToStep(newStep) {
    if (newStep === 2 && dataset.length < 4) {
      alert('Please add at least 4 data points');
      return;
    }
    if (newStep === 2) splitData();
    if (newStep === 3) {
      if (useCustomWeights) {
        weight = customWeight;
        bias = customBias;
      } else {
        weight = Math.random() * 2 - 1;
        bias = Math.random() * 2 - 1;
      }
    }
    step = newStep;
  }

  function resetDemo() {
    dataset = [];
    trainSet = [];
    testSet = [];
    weight = 0;
    bias = 0;
    lossHistory = [];
    weightHistory = [];
    biasHistory = [];
    isTraining = false;
    currentEpoch = 0;
    currentLoss = 0;
    showPrediction = false;
    step = 1;
  }
</script>

<section class="hands-on-demo">
  <h1 class="body-header">Hands-on Practice</h1>
  <p class="body-text">
    Apply what you've learned! Create your own dataset and watch linear regression train step-by-step.
  </p>

  {#if step === 1}
    <div class="demo-step">
      <h2 class="step-title">Step 1: Build Your Dataset</h2>
      
      <div class="input-group">
        <label>Feature Name (X):</label>
        <input type="text" bind:value={featureName} />
      </div>
      <div class="input-group">
        <label>Target Name (Y):</label>
        <input type="text" bind:value={targetName} />
      </div>

      <div class="data-input">
        <input id="pointX" placeholder="X value" type="number" step="0.1" />
        <input id="pointY" placeholder="Y value" type="number" step="0.1" />
        <button on:click={addDataPoint}>Add Point</button>
      </div>

      <div class="data-points">
        <h3>Data Points:</h3>
        {#each dataset as point, i}
          <div class="point-item">
            ({point.x.toFixed(2)}, {point.y.toFixed(2)})
            <button on:click={() => removePoint(i)}>×</button>
          </div>
        {/each}
      </div>

      <div class="preset-buttons">
        <button on:click={() => loadPreset('simple')}>Load Simple (8 pts)</button>
        <button on:click={() => loadPreset('large')}>Load Large (50 pts)</button>
        <button on:click={clearDataset}>Clear All</button>
      </div>

      <button class="next-btn" on:click={() => goToStep(2)}>Next: Split Data →</button>
    </div>
  {:else if step === 2}
    <div class="demo-step">
      <h2 class="step-title">Step 2: Split Data</h2>
      
      <div class="split-control">
        <label>Train Set Size: {trainSize}%</label>
        <input type="range" bind:value={trainSize} min="50" max="90" />
      </div>

      <div class="split-display">
        <div class="split-box train">
          <h3>Training Set ({trainSet.length} points)</h3>
          {#each trainSet as point}
            <span class="point-tag">({point.x.toFixed(1)}, {point.y.toFixed(1)})</span>
          {/each}
        </div>
        <div class="split-box test">
          <h3>Test Set ({testSet.length} points)</h3>
          {#each testSet as point}
            <span class="point-tag">({point.x.toFixed(1)}, {point.y.toFixed(1)})</span>
          {/each}
        </div>
      </div>

      <button class="back-btn" on:click={() => goToStep(1)}>← Back</button>
      <button class="next-btn" on:click={() => goToStep(3)}>Next: Initialize Weights →</button>
    </div>
  {:else if step === 3}
    <div class="demo-step">
      <h2 class="step-title">Step 3: Initialize Weights</h2>
      
      <div class="weight-options">
        <label>
          <input type="checkbox" bind:checked={useCustomWeights} />
          Use custom weights
        </label>
      </div>

      {#if useCustomWeights}
        <div class="custom-weights-input">
          <div class="input-group">
            <label>Weight (w):</label>
            <input type="number" bind:value={customWeight} step="0.1" />
          </div>
          <div class="input-group">
            <label>Bias (b):</label>
            <input type="number" bind:value={customBias} step="0.1" />
          </div>
        </div>
      {/if}

      <div class="weights-display">
        <div class="weight-card">
          <h3>Weight (w)</h3>
          <div class="weight-value">{(useCustomWeights ? customWeight : weight).toFixed(4)}</div>
          <p>Controls the slope</p>
        </div>
        <div class="weight-card">
          <h3>Bias (b)</h3>
          <div class="weight-value">{(useCustomWeights ? customBias : bias).toFixed(4)}</div>
          <p>Controls the intercept</p>
        </div>
      </div>

      <div class="equation-display">
        <h3>Model Equation:</h3>
        <div class="equation">
          ŷ = {(useCustomWeights ? customWeight : weight).toFixed(4)} × X + {(useCustomWeights ? customBias : bias).toFixed(4)}
        </div>
      </div>

      <button class="back-btn" on:click={() => goToStep(2)}>← Back</button>
      <button class="next-btn" on:click={() => goToStep(4)}>Next: Train Model →</button>
    </div>
  {:else if step === 4}
    <div class="demo-step wide-layout">
      <h2 class="step-title">Step 4: Train Model</h2>
      
      <div class="training-controls">
        <div class="param-input">
          <label>Learning Rate:</label>
          <input type="number" bind:value={learningRate} step="0.001" min="0.001" max="1" />
        </div>
        <div class="param-input">
          <label>Epochs:</label>
          <input type="number" bind:value={epochs} min="10" max="1000" />
        </div>
        <div class="param-input">
          <label>Speed:</label>
          <select bind:value={visualizationSpeed}>
            <option value={200}>Slow</option>
            <option value={100}>Normal</option>
            <option value={50}>Fast</option>
            <option value={20}>Very Fast</option>
          </select>
        </div>
      </div>

      <button class="train-btn" on:click={startTraining} disabled={isTraining}>
        {isTraining ? 'Training...' : 'Start Training'}
      </button>
      <button class="reset-btn" on:click={() => {isTraining = false; currentEpoch = 0; lossHistory = []; gdPath = [];}}>Reset</button>

      <div class="progress-bar">
        <div class="progress-fill" style="width: {(currentEpoch / epochs) * 100}%"></div>
      </div>
      <div class="epoch-display">Epoch: {currentEpoch} / {epochs}</div>

      <div class="metrics-grid">
        <div class="metric-card">
          <h4>Loss (MSE)</h4>
          <div class="metric-value">{currentLoss.toFixed(4)}</div>
        </div>
        <div class="metric-card">
          <h4>Weight (w)</h4>
          <div class="metric-value">{weight.toFixed(4)}</div>
        </div>
        <div class="metric-card">
          <h4>Bias (b)</h4>
          <div class="metric-value">{bias.toFixed(4)}</div>
        </div>
        <div class="metric-card">
          <h4>Gradient (dw)</h4>
          <div class="metric-value">{currentDw.toFixed(6)}</div>
        </div>
        <div class="metric-card">
          <h4>Gradient (db)</h4>
          <div class="metric-value">{currentDb.toFixed(6)}</div>
        </div>
        <div class="metric-card">
          <h4>Weight Update</h4>
          <div class="metric-value">{currentWeightUpdate.toFixed(6)}</div>
        </div>
      </div>

      <div class="visualizations-container">
        <div class="loss-visualization">
          <h3>Loss Over Epochs</h3>
          <div class="chart-container">
            <svg viewBox="0 0 400 150" class="loss-chart">
              {#if lossHistory.length > 0}
                <polyline
                  points={lossHistory.map((loss, i) => `${(i / (epochs - 1)) * 380 + 10},${140 - (loss / Math.max(...lossHistory, 1)) * 130}`).join(' ')}
                  fill="none"
                  stroke="#4caf50"
                  stroke-width="3"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                />
                {#each lossHistory as loss, i}
                  <circle
                    cx={(i / (epochs - 1)) * 380 + 10}
                    cy={140 - (loss / Math.max(...lossHistory, 1)) * 130}
                    r="4"
                    fill="#4caf50"
                  />
                {/each}
              {/if}
              <!-- Y-axis -->
              <line x1="10" y1="10" x2="10" y2="140" stroke="white" stroke-width="2" />
              <!-- X-axis -->
              <line x1="10" y1="140" x2="390" y2="140" stroke="white" stroke-width="2" />
              <!-- Grid lines -->
              <line x1="10" y1="50" x2="390" y2="50" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="10" y1="90" x2="390" y2="90" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
            </svg>
          </div>
          <div class="chart-labels">
            <span>Epoch 0</span>
            <span>Epoch {epochs}</span>
          </div>
        </div>

        <div class="gd-visualization">
          <h3>Gradient Descent Path</h3>
          <div class="chart-container">
            <svg viewBox="0 0 400 200" class="gd-chart">
              <!-- Background -->
              <rect x="0" y="0" width="400" height="200" fill="rgba(255,255,255,0.05)" rx="8" />
              
              <!-- Grid -->
              <line x1="50" y1="30" x2="50" y2="170" stroke="rgba(255,255,255,0.2)" stroke-width="1" />
              <line x1="125" y1="30" x2="125" y2="170" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="200" y1="30" x2="200" y2="170" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="275" y1="30" x2="275" y2="170" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="350" y1="30" x2="350" y2="170" stroke="rgba(255,255,255,0.2)" stroke-width="1" />
              
              <line x1="50" y1="30" x2="350" y2="30" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="50" y1="75" x2="350" y2="75" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="50" y1="120" x2="350" y2="120" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              <line x1="50" y1="165" x2="350" y2="165" stroke="rgba(255,255,255,0.1)" stroke-width="1" />
              
              <!-- Loss curve (parabolic) -->
              <path
                d="M 50 165 Q 200 30 350 165"
                fill="none"
                stroke="rgba(255,255,255,0.4)"
                stroke-width="2"
                stroke-dasharray="6,4"
              />
              
              <!-- Gradient descent path -->
              {#if gdPath.length > 0}
                <polyline
                  points={gdPath.map(p => `${p.x},${p.y}`).join(' ')}
                  fill="none"
                  stroke="#ff5722"
                  stroke-width="3"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                />
                {#each gdPath as point, i}
                  <circle
                    cx={point.x}
                    cy={point.y}
                    r={i === gdPath.length - 1 ? 6 : 4}
                    fill={i === gdPath.length - 1 ? "#ff5722" : "white"}
                    stroke="#ff5722"
                    stroke-width="2"
                  />
                {/each}
              {/if}
              
              <!-- Current point -->
              {#if gdPath.length > 0}
                <circle
                  cx={gdPath[gdPath.length - 1].x}
                  cy={gdPath[gdPath.length - 1].y}
                  r="10"
                  fill="none"
                  stroke="#ff5722"
                  stroke-width="2"
                  class="pulse-ring"
                />
              {/if}
              
              <!-- Axes -->
              <line x1="50" y1="30" x2="50" y2="170" stroke="white" stroke-width="2" />
              <line x1="50" y1="165" x2="350" y2="165" stroke="white" stroke-width="2" />
              
              <!-- Axis labels -->
              <text x="45" y="25" fill="white" font-size="11" text-anchor="end">Loss</text>
              <text x="355" y="180" fill="white" font-size="11">Weight</text>
            </svg>
          </div>
          <div class="chart-labels">
            <span>Weight: -10</span>
            <span>Weight: +10</span>
          </div>
        </div>
      </div>

      <button class="back-btn" on:click={() => goToStep(3)}>← Back</button>
      <button class="next-btn" on:click={() => goToStep(5)} disabled={currentEpoch < epochs}>Next: Make Predictions →</button>
    </div>
  {:else if step === 5}
    <div class="demo-step">
      <h2 class="step-title">Step 5: Make Predictions</h2>
      
      <div class="prediction-input">
        <label>Enter {featureName}:</label>
        <input type="number" bind:value={predictionInput} placeholder="Enter value" step="0.1" />
        <button on:click={makePrediction}>Predict</button>
      </div>

      {#if showPrediction}
        <div class="prediction-result">
          <h3>Prediction Result:</h3>
          <div class="result-value">
            Predicted {targetName}: {typeof predictedValue === 'string' ? predictedValue : predictedValue.toFixed(3)}
          </div>
          <div class="result-equation">
            Using: ŷ = {weight.toFixed(4)} × {parseFloat(predictionInput).toFixed(2)} + {bias.toFixed(4)}
          </div>
        </div>
      {/if}

      <div class="final-model">
        <h3>Final Model:</h3>
        <div class="equation">
          ŷ = {weight.toFixed(4)} × X + {bias.toFixed(4)}
        </div>
      </div>

      <button class="back-btn" on:click={() => goToStep(4)}>← Back</button>
      <button class="reset-btn" on:click={resetDemo}>Start Over</button>
    </div>
  {/if}
</section>

